const body = items[0].json.body || items[0].json;
const reservation = body.reservation || {};

const status = body.status || '';
const reason = body.reason || 'Sin motivo especificado';
const reservationId = body.reservationId || reservation.id;

// Customer info from reservation
const email = reservation.email || '';
const name = reservation.name || reservation.customer_name || 'Cliente';
const phone = reservation.phone || '';
const eventDate = reservation.event_date || '';
const timeSlot = reservation.time_slot || '';
const calendarEventId = reservation.google_calendar_event_id || '';

// Format date
let fechaFormateada = eventDate;
try {
  if (eventDate) {
    const d = new Date(eventDate);
    fechaFormateada = d.toLocaleDateString('es-ES', { day: 'numeric', month: 'long', year: 'numeric' });
  }
} catch(e) {}

const timeSlotLabels = { morning: 'Manana', afternoon: 'Tarde', night: 'Noche' };
const franjaLabel = timeSlotLabels[timeSlot] || timeSlot;

const isRejected = status === 'rejected';
const statusLabel = isRejected ? 'rechazada' : 'cancelada';
const subject = isRejected
  ? `Tu reserva en Happyhub ha sido rechazada`
  : `Tu reserva en Happyhub ha sido cancelada`;

const html = `
<div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px;">
  <div style="text-align: center; margin-bottom: 30px;">
    <h1 style="color: #1a1a1a; font-size: 24px;">Happyhub</h1>
  </div>
  <p>Hola <strong>${name}</strong>,</p>
  <p>Te informamos de que tu reserva ha sido <strong>${statusLabel}</strong>.</p>
  <div style="background: #f8f8f8; border-radius: 12px; padding: 20px; margin: 20px 0;">
    <p style="margin: 5px 0;"><strong>Reserva:</strong> #${reservationId}</p>
    <p style="margin: 5px 0;"><strong>Fecha:</strong> ${fechaFormateada}</p>
    <p style="margin: 5px 0;"><strong>Franja:</strong> ${franjaLabel}</p>
  </div>
  <div style="background: ${isRejected ? '#fef2f2' : '#fff7ed'}; border-left: 4px solid ${isRejected ? '#dc2626' : '#f97316'}; border-radius: 8px; padding: 16px; margin: 20px 0;">
    <p style="margin: 0; font-weight: bold; color: ${isRejected ? '#dc2626' : '#f97316'};">Motivo:</p>
    <p style="margin: 8px 0 0 0;">${reason}</p>
  </div>
  <p>Si tienes alguna duda, contactanos por WhatsApp al <a href="https://wa.me/34624645517">624 645 517</a>.</p>
  <p style="color: #666; font-size: 12px; margin-top: 30px;">Este es un mensaje automatico de Happyhub.</p>
</div>
`;

return [{
  json: {
    reservationId,
    status,
    reason,
    email,
    name,
    subject,
    html,
    calendarEventId,
    hasCalendarEvent: !!calendarEventId
  }
}];

// Merge data back after calendar deletion (or skip)
const prepData = $('PrepararDatos').item.json;
return [{ json: prepData }];
